#!/usr/bin/env python3
"""Minimal VT100 emulator: render captured pty output into final screen frame(s).
Handles: CSI H/f, J, K, m, ?1049h/l, ?25h/l, CR, LF, BS, printable UTF-8.
Optionally dumps every frame where screen changed (split on ?25h show-cursor)."""
import sys, re

class Term:
    def __init__(self, rows=24, cols=80):
        self.rows, self.cols = rows, cols
        self.scr = [[' ']*cols for _ in range(rows)]
        self.attr = [[None]*cols for _ in range(rows)]
        self.r = self.c = 0
        self.cur_attr = ()
    def clear(self):
        self.scr = [[' ']*self.cols for _ in range(self.rows)]
        self.attr = [[None]*self.cols for _ in range(self.rows)]
    def put(self, ch):
        if 0 <= self.r < self.rows and 0 <= self.c < self.cols:
            self.scr[self.r][self.c] = ch
            self.attr[self.r][self.c] = self.cur_attr
        self.c += 1
    def text(self):
        return '\n'.join(''.join(row).rstrip() for row in self.scr)
    def attrdump(self):
        lines = []
        for row in self.attr:
            line = ''
            for a in row:
                if a is None: line += ' '
                else:
                    s = ''
                    if 'bold' in a: s += 'B'
                    if 'dim' in a: s += 'D'
                    if 'italic' in a: s += 'I'
                    if 'under' in a: s += 'U'
                    if 'rev' in a: s += 'R'
                    fg = next((x for x in a if x.startswith('fg')), None)
                    bg = next((x for x in a if x.startswith('bg')), None)
                    if fg: s += fg[2:4]
                    if bg: s += 'g'+bg[2:4]
                    line += s[0] if s else '?'
            lines.append(line.rstrip())
        return '\n'.join(lines)

SGR_MAP = {'1':'bold','2':'dim','3':'italic','4':'under','7':'rev'}

def emulate(data, rows, cols, split_frames=False):
    t = Term(rows, cols)
    frames = []
    i = 0
    attr = set()
    text = data.decode('utf-8', errors='replace')
    while i < len(text):
        ch = text[i]
        if ch == '\x1b':
            m = re.match(r'\x1b\[([0-9;?]*)([A-Za-z@`~])', text[i:])
            if m:
                params, cmd = m.group(1), m.group(2)
                i += m.end()
                if cmd in 'Hf':
                    p = params.split(';') if params else []
                    t.r = (int(p[0])-1) if len(p)>=1 and p[0] else 0
                    t.c = (int(p[1])-1) if len(p)>=2 and p[1] else 0
                elif cmd == 'J':
                    if params in ('2','3',''): t.clear()
                elif cmd == 'm':
                    for p in (params.split(';') if params else ['0']):
                        if p in ('0',''): attr = set()
                        elif p in SGR_MAP: attr.add(SGR_MAP[p])
                        elif p == '22': attr.discard('bold'); attr.discard('dim')
                        elif p == '23': attr.discard('italic')
                        elif p == '24': attr.discard('under')
                        elif p == '27': attr.discard('rev')
                        elif p == '39': attr = {x for x in attr if not x.startswith('fg')}
                        elif p == '49': attr = {x for x in attr if not x.startswith('bg')}
                        elif 30 <= int(p) <= 37 if p.isdigit() else False: attr.add('fg%d'%int(p))
                        elif 40 <= int(p) <= 47 if p.isdigit() else False: attr.add('bg%d'%int(p))
                        elif p == '38' or p == '48': pass  # extended, handled crudely
                    t.cur_attr = tuple(sorted(attr))
                elif cmd == 'h' and '?25' in params:
                    if split_frames:
                        frames.append((t.text(), t.attrdump()))
                continue
            m = re.match(r'\x1b\[[0-9;?]*[ -/]*.', text[i:], re.S)
            if m:
                i += m.end(); continue
            i += 1; continue
        elif ch == '\r': t.c = 0
        elif ch == '\n': t.r += 1
        elif ch == '\x08': t.c = max(0, t.c-1)
        elif ch == '\x07': pass
        else:
            t.put(ch)
        i += 1
    return t, frames

if __name__ == '__main__':
    path = sys.argv[1]
    rows = int(sys.argv[2]) if len(sys.argv) > 2 else 24
    cols = int(sys.argv[3]) if len(sys.argv) > 3 else 80
    mode = sys.argv[4] if len(sys.argv) > 4 else 'final'
    data = open(path, 'rb').read()
    t, frames = emulate(data, rows, cols, split_frames=(mode=='frames'))
    if mode == 'frames':
        seen = set()
        for txt, at in frames:
            if txt not in seen:
                seen.add(txt)
                print(txt)
                print('=' * cols)
                print(at)
                print('#' * cols)
    else:
        print(t.text())
        print('=' * cols)
        print(t.attrdump())

